while(<$fh>){chomp; if(/^>(\S+)/){$n=$1;$s{$n}=''}elsif(length){$s{$n}.=uc($_);}}
sub rc { my $x=reverse shift; $x=~tr/ACGT/TGCA/; return $x; }
sub tm { my $seq=shift; my $v=`oligotm -tp 1 -sc 1 -mv 50 -dv 2 -n 0.8 -d 500 $seq`; chomp $v; return $v+0; }
sub table {
  my($name,$seq)=@_;
  print "\n=== $name ===\n";
